import requests, numpy as np, matplotlib.pyplot as plt
r=requests.get("https://alphafold.ebi.ac.uk/files/AF-A6NDA9-F1-model_v6.pdb",headers={"User-Agent":"a/1"},timeout=180)
bb={}
for l in r.text.splitlines():
    if l.startswith("ATOM"):
        rn=int(l[22:26]); nm=l[12:16].strip()
        if nm in ("N","CA","C","O"):
            bb.setdefault(rn,{})[nm]=np.array([float(l[30:38]),float(l[38:46]),float(l[46:54])])
res=sorted(bb)
def dih(p0,p1,p2,p3):
    b0,b1,b2=p0-p1,p2-p1,p3-p2
    b1n=b1/np.linalg.norm(b1)
    v=b0-(b0@b1n)*b1n; w=b2-(b2@b1n)*b1n
    return np.degrees(np.arctan2(np.cross(b1n,v)@w, v@w))
phi={};psi={}
for i in res:
    if i-1 in bb: phi[i]=dih(bb[i-1]["C"],bb[i]["N"],bb[i]["CA"],bb[i]["C"])
    if i+1 in bb: psi[i]=dih(bb[i]["N"],bb[i]["CA"],bb[i]["C"],bb[i+1]["N"])
def ss(i):
    if i not in phi or i not in psi: return "-"
    p,s=phi[i],psi[i]
    if -180<=p<=-20 and (s>=80 or s<=-150): return "E"   # beta / extended
    if -160<=p<=-20 and -80<=s<=20: return "H"           # helix
    return "-"
# backbone H-bond (N...O < 3.5 A, |i-j|>3) to confirm sheet pairing
hb=[(i,jj) for i in res for jj in res if abs(i-jj)>3 and np.linalg.norm(bb[i]["N"]-bb[jj]["O"])<3.5]
hbset=set(hb)
ig=list(range(253,342))
sstr="".join(ss(i) for i in ig)
print("Ig-like domain 253-341 secondary structure (E=extended/beta, H=helix):")
for off in range(0,len(ig),60):
    print(f"  {ig[off]:>3} {sstr[off:off+60]}")
segs=[];cur=[]
for i in ig:
    if ss(i)=="E": cur.append(i)
    else:
        if len(cur)>=3: segs.append((cur[0],cur[-1]))
        cur=[]
if len(cur)>=3: segs.append((cur[0],cur[-1]))
print("\nbeta strands (>=3 consecutive extended residues):", segs)
print("SS at 294-300:", {i:ss(i) for i in range(294,301)})
inloop=[(segs[k][1]+1,segs[k+1][0]-1) for k in range(len(segs)-1)]
for a,b in inloop:
    if a<=297<=b:
        print(f"D297 is in the inter-strand loop {a}-{b} (length {b-a+1} aa), between strands {segs[[x[0] for x in inloop].index((a,b))]} and the next")
nhb297=[x for x in hb if 297 in x]
print("backbone H-bonds involving residue 297:", nhb297)

# per-residue burial across whole chain for context
ca={i:bb[i]["CA"] for i in res}
nb={i:sum(1 for k in res if k!=i and np.linalg.norm(ca[k]-ca[i])<10) for i in res}
igv=[nb[i] for i in ig]
fig,axes=plt.subplots(1,2,figsize=(12,4.2))
ax=axes[0]
ax.plot(ig,igv,color="#2b2b2b",lw=1.2)
ax.axhline(np.mean(igv),ls="--",color="grey",lw=0.8)
ax.scatter([297],[nb[297]],color="crimson",zorder=5,s=50)
ax.annotate("D297 (insertion point)\n11 neighbours, 4th percentile",xy=(297,nb[297]),xytext=(303,26),color="crimson",fontsize=8.5,
            arrowprops=dict(arrowstyle="->",color="crimson"))
for a,b in segs: ax.axvspan(a,b,color="steelblue",alpha=0.25)
ax.set_xlabel("residue"); ax.set_ylabel("CA neighbours within 10 A")
ax.set_title("Burial across the Ig-like domain\n(blue bands = beta strands)",fontsize=10)

ax=axes[1]
P=np.array([ca[i] for i in ig]); c=P.mean(0)
u,s,vt=np.linalg.svd(P-c)
proj=(P-c)@vt[0]; proj2=(P-c)@vt[1]
sc=ax.scatter(proj,proj2,c=igv,cmap="viridis",s=16)
i297=ig.index(297)
ax.scatter([proj[i297]],[proj2[i297]],facecolors="none",edgecolors="crimson",s=160,lw=2)
ax.annotate("D297",(proj[i297],proj2[i297]),xytext=(8,8),textcoords="offset points",color="crimson",fontsize=10)
for lab,rn in [("253 (N-term, LRRCT side)",253),("341 (C-term, FN3 side)",341)]:
    k=ig.index(rn); ax.annotate(lab,(proj[k],proj2[k]),xytext=(5,-12),textcoords="offset points",fontsize=7.5)
plt.colorbar(sc,ax=ax,label="CA neighbours (10 A)")
ax.set_xlabel("Ig domain long axis (A)"); ax.set_ylabel("second principal axis (A)")
ax.set_title("Ig-like domain projection: the insertion point\nis a surface loop at the FN3-proximal end",fontsize=10)
plt.tight_layout(); plt.show()
